  "caps.skillDesc.init": "为当前项目建立全局记忆与架构约定。它会分析代码结构、规范和测试命令，并生成记忆文件，让智能体在后续对话中更懂您的项目。",
  "caps.skillDesc.explore": "通过隔离的子智能体大范围探索整个代码库，适合解答跨文件问题。例如：'找出所有使用旧版接口的地方'或'梳理登录流程'。",
  "caps.skillDesc.research": "深度技术调研助手。它能结合网页搜索与本地代码阅读，为您解答类似'如何将 X 升级到 Y'或'对比我们的实现和官方最佳实践'的难题。",
  "caps.skillDesc.install-capability": "技能与 MCP 插件管理器。可以通过网址、GitHub、本地路径等一键安装或卸载扩展能力。",
  "caps.skillDesc.review": "严格审查当前分支的代码变更。它会指出逻辑错误、安全隐患和未测试的代码，并给出详细的修改建议。",
  "caps.skillDesc.security-review": "安全专家视角的代码审查。专门扫描代码注入、越权、硬编码密钥和目录遍历等高危安全隐患。",
  "caps.skillDesc.test": "自动化跑测专家。它能运行项目的测试套件，自动诊断失败原因并尝试修复代码，直到测试全部通过为止。",
  "caps.skillDesc.browser-auto": "浏览器自动化数字员工。能够驱使真实的 Chrome/Edge 浏览器帮您自动上网查资料、填表单、抓取网页，处理连贯的网页交互任务。",
  "caps.skillDesc.desktop-auto": "桌面图形界面自动化数字员工。能像真人一样观察您的屏幕、控制鼠标和键盘，专用于必须点选图形界面的本地客户端软件（如 WPS、Excel）。查系统信息、管文件/进程这类无需界面的电脑操作不归它管——直接用代码调用更准更快。",
  "caps.skillDesc.ppt-auto": "PPT 演示文稿生成助手。根据您提供的主题，通过 SVG 路径或模板填充方式生成专业 PPT，支持多种布局与质量检查。",
